    public static function index():void
    {
        AdminGuard::enforce('validations.view');$pdo=Database::connection();[$scope,$p]=ValidationAccess::scopeSql('v');$where=[$scope];
        foreach(['pv_number'=>'v.pv_number','name'=>'v.name','status'=>'v.status'] as $key=>$column)if(($value=trim((string)($_GET[$key]??'')))!==''){$where[]=$key==='status'?"$column=:$key":"$column LIKE :$key";$p[$key]=$key==='status'?$value:"%$value%";}
        $unit=(int)($_GET['unit_id']??$_GET['unit']??0);if($unit){$where[]='v.unit_id=:unit_id';$p['unit_id']=$unit;}
        $page=max(1,(int)($_GET['page']??1));$perPage=10;$whereSql=implode(' AND ',$where);$count=$pdo->prepare("SELECT COUNT(*) FROM validations v WHERE {$whereSql}");$count->execute($p);$total=(int)$count->fetchColumn();$pages=max(1,(int)ceil($total/$perPage));$page=min($page,$pages);$offset=($page-1)*$perPage;
        $q=$pdo->prepare("SELECT v.*,u.name unit_name,(SELECT COUNT(*) FROM validation_phases x WHERE x.validation_id=v.id AND x.status<>'inactive') phase_count,(SELECT COUNT(*) FROM samples s WHERE s.validation_id=v.id) sample_count FROM validations v LEFT JOIN units u ON u.id=v.unit_id WHERE {$whereSql} ORDER BY v.start_date DESC,v.id DESC LIMIT {$perPage} OFFSET {$offset}");$q->execute($p);
        [$kScope,$kp]=ValidationAccess::scopeSql('v','kpi_user');$k=$pdo->prepare("SELECT status,COUNT(*) total FROM validations v WHERE {$kScope} GROUP BY status");$k->execute($kp);$kpis=$k->fetchAll(PDO::FETCH_KEY_PAIR);
        self::view('index',['validations'=>$q->fetchAll(),'kpis'=>$kpis,'units'=>ValidationAccess::units(),'page'=>$page,'pages'=>$pages,'total'=>$total,'perPage'=>$perPage,'pageTitle'=>'Validações','pageSubtitle'=>'Cadastre protocolos de validação, acompanhe etapas e registre resultados.']);
    }
    public static function create():void {AdminGuard::enforce('validations.create');self::view('form',['validation'=>[],'errors'=>[],'units'=>ValidationAccess::units(),'pageTitle'=>'Nova validação']);}
    public static function store():void
    {
        AdminGuard::enforce('validations.create');self::csrf('/validations/create');$d=self::posted();$errors=self::validate($d);if($errors){self::view('form',['validation'=>$d,'errors'=>$errors,'units'=>ValidationAccess::units(),'pageTitle'=>'Nova validação']);return;}$pdo=Database::connection();$pdo->beginTransaction();try{$pdo->prepare('INSERT INTO validations(pv_number,name,description,unit_id,start_date,expected_end_date,status,created_by,updated_by) VALUES(:pv_number,:name,:description,:unit_id,:start_date,:expected_end_date,:status,:user,:user2)')->execute($d+['user'=>Auth::user()['id'],'user2'=>Auth::user()['id']]);$id=(int)$pdo->lastInsertId();$pdo->prepare("INSERT INTO validation_phases(validation_id,name,sequence_order,status,created_by) VALUES(:id,'Etapa 1',1,'active',:user)")->execute(['id'=>$id,'user'=>Auth::user()['id']]);Auth::registerAudit('VALIDATION_CREATED','validations',$id,null,$d);Auth::registerAudit('VALIDATION_PHASE_CREATED','validation_phases',(int)$pdo->lastInsertId(),null,['validation_id'=>$id,'name'=>'Etapa 1']);$pdo->commit();Flash::set('success','Validação criada com Etapa 1.');self::redirect('/validations/view?id='.$id);}catch(\Throwable $e){if($pdo->inTransaction())$pdo->rollBack();self::view('form',['validation'=>$d,'errors'=>[$e instanceof \PDOException?'Não foi possível salvar. Verifique o número PV e a unidade.':$e->getMessage()],'units'=>ValidationAccess::units(),'pageTitle'=>'Nova validação']);}
