    public static function dashboard():void
    {AdminGuard::enforce('validations.view');$v=self::find();if(!$v){self::notFound();return;}$data=ValidationDashboardService::build((int)$v['id'],(int)($_GET['phase']??0),(int)($_GET['test']??0));self::view('dashboard',$data+['validation'=>$v,'pageTitle'=>'Dashboard '.$v['pv_number'],'pageSubtitle'=>$v['name'].' — '.($v['unit_name']??'')]);}
    public static function dashboardSelection():void
    {
        AdminGuard::enforce('validations.view');
        [$scope,$params]=ValidationAccess::scopeSql('v');
        $sql="SELECT v.id,v.pv_number,v.name,v.start_date,v.expected_end_date,v.actual_end_date,v.status,
                    u.name unit_name,creator.name responsible_name,
                    GROUP_CONCAT(DISTINCT CONCAT(bc.code,' — ',bc.name) ORDER BY bc.code SEPARATOR '||') component_names
              FROM validations v
              LEFT JOIN units u ON u.id=v.unit_id
              LEFT JOIN users creator ON creator.id=v.created_by
              LEFT JOIN validation_blood_components vbc ON vbc.validation_id=v.id AND vbc.status='active'
              LEFT JOIN blood_components bc ON bc.id=vbc.blood_component_id
             WHERE {$scope}
             GROUP BY v.id,v.pv_number,v.name,v.start_date,v.expected_end_date,v.actual_end_date,v.status,u.name,creator.name
             ORDER BY FIELD(v.status,'in_progress','planned','completed','cancelled'),v.start_date DESC,v.id DESC";
        $query=Database::connection()->prepare($sql);$query->execute($params);
        self::view('dashboard_selection',['validations'=>$query->fetchAll(PDO::FETCH_ASSOC),'pageTitle'=>'Dashboard de Validações','pageSubtitle'=>'Selecione uma validação para abrir o dashboard.']);
    }
    public static function plan():void
    {
        AdminGuard::enforce('validations.view');$v=self::find();if(!$v){self::notFound();return;}$pdo=Database::connection();$ph=$pdo->prepare("SELECT * FROM validation_phases WHERE validation_id=:id AND status<>'inactive' ORDER BY sequence_order");$ph->execute(['id'=>$v['id']]);$phases=$ph->fetchAll();$last=$phases?end($phases):null;$phase=(int)($_GET['phase_id']??($last['id']??0));if(!in_array($phase,array_map('intval',array_column($phases,'id')),true))$phase=(int)($last['id']??0);$selectedPhase=current(array_filter($phases,static fn($p)=>(int)$p['id']===$phase))?:null;$tests=$pdo->prepare("SELECT bc.id component_id,bc.code component_code,bc.name component_name,t.id test_id,t.name test_name,t.result_type,t.unit,tbc.is_required default_required,vt.id selected,vt.is_required FROM blood_components bc JOIN test_blood_components tbc ON tbc.blood_component_id=bc.id JOIN tests t ON t.id=tbc.test_id AND t.status='active' LEFT JOIN validation_tests vt ON vt.validation_id=:id AND vt.phase_id=:phase AND vt.blood_component_id=bc.id AND vt.test_id=t.id AND vt.status='active' WHERE bc.status='active' ORDER BY bc.code,t.name");$tests->execute(['id'=>$v['id'],'phase'=>$phase]);self::view('plan',['validation'=>$v,'phases'=>$phases,'phase'=>$phase,'selectedPhase'=>$selectedPhase,'tests'=>$tests->fetchAll(),'pageTitle'=>'Plano de testes']);
    }
    public static function savePlan():void
    {
        AdminGuard::enforce('validations.configure_tests');self::csrf('/validations');$v=self::find(true);if(!$v){self::notFound();return;}if(in_array($v['status'],['completed','cancelled'],true)){Flash::set('error','Validação em modo somente leitura.');self::redirect('/validations/view?id='.$v['id']);}$phase=(int)($_POST['phase_id']??0);$chosen=(array)($_POST['tests']??[]);$pdo=Database::connection();$pdo->beginTransaction();try{$pdo->prepare('DELETE FROM validation_tests WHERE validation_id=:id AND phase_id=:phase')->execute(['id'=>$v['id'],'phase'=>$phase]);$pdo->prepare('DELETE FROM validation_blood_components WHERE validation_id=:id AND phase_id=:phase')->execute(['id'=>$v['id'],'phase'=>$phase]);$insC=$pdo->prepare("INSERT IGNORE INTO validation_blood_components(validation_id,blood_component_id,phase_id,status) VALUES(:v,:c,:p,'active')");$insT=$pdo->prepare("INSERT INTO validation_tests(validation_id,phase_id,blood_component_id,test_id,is_required,status) SELECT :v,:p,:c,tbc.test_id,:required,'active' FROM test_blood_components tbc WHERE tbc.blood_component_id=:c2 AND tbc.test_id=:t");foreach($chosen as$c=>$items){$c=(int)$c;foreach((array)$items as$t=>$settings){$insC->execute(['v'=>$v['id'],'c'=>$c,'p'=>$phase]);$insT->execute(['v'=>$v['id'],'p'=>$phase,'c'=>$c,'required'=>!empty($settings['required'])?1:0,'c2'=>$c,'t'=>(int)$t]);}}Auth::registerAudit('VALIDATION_TEST_PLAN_UPDATED','validations',(int)$v['id'],null,['phase_id'=>$phase,'tests'=>$chosen]);$pdo->commit();Flash::set('success','Plano de testes salvo.');}catch(\Throwable $e){if($pdo->inTransaction())$pdo->rollBack();Flash::set('error',$e->getMessage());}self::redirect('/validations/plan?id='.$v['id'].'&phase_id='.$phase);
    }
    public static function results():void
    {
        AdminGuard::enforce('validations.view');$v=self::find();if(!$v){self::notFound();return;}$pdo=Database::connection();$f=['phase'=>(int)($_GET['phase']??0),'component'=>(int)($_GET['component']??0),'origin'=>(int)($_GET['origin']??0),'received_date'=>trim((string)($_GET['received_date']??'')),'donation'=>trim((string)($_GET['donation']??'')),'lcqh'=>trim((string)($_GET['lcqh']??'')),'status'=>trim((string)($_GET['status']??''))];$where=["s.validation_id=:id","s.status IN('received','in_analysis','partial_results','completed')"];$p=['id'=>$v['id']];foreach([['phase','s.validation_phase_id'],['component','s.blood_component_id'],['origin','s.origin_unit_id']]as[$k,$c])if($f[$k]){$where[]="$c=:$k";$p[$k]=$f[$k];}if($f['received_date']!==''){$where[]='DATE(s.received_at)=:received_date';$p['received_date']=$f['received_date'];}foreach([['donation','s.donation_number'],['lcqh','s.lcqh_code']]as[$k,$c])if($f[$k]!==''){$where[]="$c LIKE :$k";$p[$k]='%'.$f[$k].'%';}if($f['status']!==''){$where[]='s.status=:status';$p['status']=$f['status'];}$q=$pdo->prepare("SELECT s.*,bc.code component_code,bc.name component_name,bc.density,u.name origin_name,v.pv_number,vp.name phase_name,b.name bag_brand_name,b.reference_number,pv.name preservative_name,pv.code preservative_code,(SELECT bt.tare_weight FROM bag_brand_tares bt JOIN bag_brand_tare_components btc ON btc.bag_brand_tare_id=bt.id WHERE bt.bag_brand_id=s.bag_brand_id AND btc.blood_component_id=s.blood_component_id AND bt.active=1 ORDER BY bt.id LIMIT 1) resolved_tare FROM samples s JOIN validations v ON v.id=s.validation_id JOIN validation_phases vp ON vp.id=s.validation_phase_id JOIN blood_components bc ON bc.id=s.blood_component_id LEFT JOIN units u ON u.id=s.origin_unit_id LEFT JOIN bag_brands b ON b.id=s.bag_brand_id LEFT JOIN preservatives pv ON pv.id=b.preservative_id WHERE ".implode(' AND ',$where)." ORDER BY bc.code,s.received_at DESC");$q->execute($p);$samples=$q->fetchAll();foreach($samples as&$s){$t=$pdo->prepare("SELECT t.*,vt.is_required,tr.result_value_numeric,tr.result_value_text,e.conformity_status,e.specification_snapshot_text FROM validation_tests vt JOIN tests t ON t.id=vt.test_id LEFT JOIN sample_tests st ON st.sample_id=:sample AND st.test_id=t.id LEFT JOIN test_results tr ON tr.sample_test_id=st.id LEFT JOIN test_result_spec_evaluations e ON e.test_result_id=tr.id WHERE vt.validation_id=:validation AND vt.blood_component_id=:component AND vt.status='active' AND (vt.phase_id=:phase OR vt.phase_id IS NULL) ORDER BY t.name");$t->execute(['sample'=>$s['id'],'validation'=>$v['id'],'component'=>$s['blood_component_id'],'phase'=>$s['validation_phase_id']]);$s['tests']=$t->fetchAll();$s['test_codes']=array_column($s['tests'],'code');$s['dependencies']=LaboratoryDependencyResolver::resolve($s['test_codes']);$s['laboratory']=ValidationResultService::state((int)$s['id']);$s['outside']=ValidationResultService::nonconforming((int)$s['id'],(int)$v['id']);$s['missing']=ValidationResultService::missing($s);}$components=$pdo->prepare("SELECT DISTINCT bc.id,bc.code,bc.name FROM samples s JOIN blood_components bc ON bc.id=s.blood_component_id WHERE s.validation_id=:id ORDER BY bc.code");$components->execute(['id'=>$v['id']]);$phases=$pdo->prepare("SELECT id,name FROM validation_phases WHERE validation_id=:id AND status='active' ORDER BY sequence_order");$phases->execute(['id'=>$v['id']]);$origins=$pdo->prepare("SELECT DISTINCT u.id,u.name FROM samples s JOIN units u ON u.id=s.origin_unit_id WHERE s.validation_id=:id ORDER BY u.name");$origins->execute(['id'=>$v['id']]);$stats=$pdo->prepare("SELECT COUNT(*) samples,SUM(status='completed') completed,SUM(status<>'completed') pending,(SELECT COUNT(*) FROM test_results tr JOIN sample_tests st ON st.id=tr.sample_test_id JOIN samples x ON x.id=st.sample_id WHERE x.validation_id=:id2) results FROM samples WHERE validation_id=:id");$stats->execute(['id'=>$v['id'],'id2'=>$v['id']]);$canEdit=Permission::can('validations.enter_results')&&!in_array($v['status'],['completed','cancelled'],true);self::view('results',['validation'=>$v,'samples'=>$samples,'components'=>$components->fetchAll(),'phases'=>$phases->fetchAll(),'origins'=>$origins->fetchAll(),'filters'=>$f,'stats'=>$stats->fetch(),'canEdit'=>$canEdit,'pageTitle'=>'Resultados '.$v['pv_number'],'pageSubtitle'=>$v['name'].' — '.($v['unit_name']??'')]);
    }
    public static function saveResult():void {AdminGuard::enforce('validations.enter_results');self::csrf('/validations');$v=self::find(true);if(!$v){self::notFound();return;}[$saved,$errors]=ValidationResultService::saveBatch((int)$v['id'],(array)($_POST['samples']??[]));Flash::set($errors?'error':'success',$saved.' amostra(s) salva(s).'.($errors?' '.implode(' | ',$errors):''));self::redirect('/validations/results?id='.$v['id']);}
    public static function completeSample():void {AdminGuard::enforce('validations.enter_results');self::csrf('/validations');$v=self::find(true);if(!$v){self::notFound();return;}[$saved,$saveErrors]=ValidationResultService::saveBatch((int)$v['id'],(array)($_POST['samples']??[]));$ids=array_filter(array_map('intval',explode(',',(string)($_POST['visible_ids']??''))));[$done,$pending,$errors]=ValidationResultService::completeEligible((int)$v['id'],$ids,!empty($_POST['specification_acknowledged']));$errors=array_merge($saveErrors,$errors);$message=$done.' amostra(s) concluída(s). '.count($pending).' permaneceram pendentes.';if($errors)$message.=' '.implode(' | ',$errors);Flash::set(($pending||$errors)?'error':'success',$message);self::redirect('/validations/results?id='.$v['id']);}
    public static function complete():void {AdminGuard::enforce('validations.complete');self::csrf('/validations');$v=self::find(true);if(!$v){self::notFound();return;}$pdo=Database::connection();$q=$pdo->prepare("SELECT COUNT(*) total,SUM(status<>'completed') pending FROM samples WHERE validation_id=:id");$q->execute(['id'=>$v['id']]);$counts=$q->fetch(PDO::FETCH_ASSOC);$plan=$pdo->prepare("SELECT COUNT(*) FROM validation_tests WHERE validation_id=:id AND status='active'");$plan->execute(['id'=>$v['id']]);if($v['status']!=='in_progress'||!(int)$plan->fetchColumn()||!(int)$counts['total']||(int)$counts['pending']){Flash::set('error','A validação só pode ser concluída em andamento, com plano configurado e todas as amostras concluídas.');self::redirect('/validations/view?id='.$v['id']);}$pdo->prepare("UPDATE validations SET status='completed',actual_end_date=CURDATE(),updated_by=:u WHERE id=:id")->execute(['u'=>Auth::user()['id'],'id'=>$v['id']]);Auth::registerAudit('VALIDATION_COMPLETED','validations',(int)$v['id'],$v,['status'=>'completed','actual_end_date'=>date('Y-m-d')]);Flash::set('success','Validação concluída.');self::redirect('/validations/view?id='.$v['id']);}
    public static function storeWithPhaseCycle():void
    {
        AdminGuard::enforce('validations.create');self::csrf('/validations/create');$d=self::posted();$errors=self::validate($d);if($errors){self::view('form',['validation'=>$d,'errors'=>$errors,'units'=>ValidationAccess::units(),'pageTitle'=>'Nova validação']);return;}
        $pdo=Database::connection();$pdo->beginTransaction();
        try{
            $user=(int)Auth::user()['id'];$pdo->prepare('INSERT INTO validations(pv_number,name,description,unit_id,start_date,expected_end_date,status,created_by,updated_by) VALUES(:pv_number,:name,:description,:unit_id,:start_date,:expected_end_date,:status,:user,:user2)')->execute($d+['user'=>$user,'user2'=>$user]);$id=(int)$pdo->lastInsertId();
            $pdo->prepare("INSERT INTO validation_phases(validation_id,name,sequence_order,status,started_at,created_by) VALUES(:validation,'Etapa 1',1,'active',:started,:user)")->execute(['validation'=>$id,'started'=>$d['start_date'].' 00:00:00','user'=>$user]);$phase=(int)$pdo->lastInsertId();
            Auth::registerAudit('VALIDATION_CREATED','validations',$id,null,$d);Auth::registerAudit('VALIDATION_PHASE_CREATED','validation_phases',$phase,null,['validation_id'=>$id,'name'=>'Etapa 1','sequence_order'=>1]);Auth::registerAudit('VALIDATION_PHASE_STARTED','validation_phases',$phase,null,['validation_id'=>$id,'started_at'=>$d['start_date']]);
            $pdo->commit();InternalNotificationService::notifyUnit((int)$d['unit_id'],'validations.view','validation.created','Validação criada',$d['pv_number'].' — '.$d['name'],'/validations/view?id='.$id,'validations',$id,$user);Flash::set('success','Validação criada com Etapa 1.');self::redirect('/validations/view?id='.$id);
        }catch(\Throwable $e){if($pdo->inTransaction())$pdo->rollBack();self::view('form',['validation'=>$d,'errors'=>[$e instanceof \PDOException?'Não foi possível salvar. Verifique o número PV e a unidade.':$e->getMessage()],'units'=>ValidationAccess::units(),'pageTitle'=>'Nova validação']);}
    }

    public static function savePhasePlan():void
    {
        AdminGuard::enforce('validations.configure_tests');self::csrf('/validations');$v=self::find(true);if(!$v){self::notFound();return;}
        $phase=(int)($_POST['phase_id']??0);$pdo=Database::connection();$q=$pdo->prepare("SELECT status FROM validation_phases WHERE id=:phase AND validation_id=:validation");$q->execute(['phase'=>$phase,'validation'=>$v['id']]);
        if($q->fetchColumn()!=='active'||in_array($v['status'],['completed','cancelled'],true)){Flash::set('error','O plano de uma etapa concluída é somente leitura.');self::redirect('/validations/plan?id='.$v['id'].'&phase_id='.$phase);}
        $chosen=(array)($_POST['tests']??[]);$pdo->beginTransaction();
        try{
            $pdo->prepare('DELETE FROM validation_tests WHERE validation_id=:id AND phase_id=:phase')->execute(['id'=>$v['id'],'phase'=>$phase]);$pdo->prepare('DELETE FROM validation_blood_components WHERE validation_id=:id AND phase_id=:phase')->execute(['id'=>$v['id'],'phase'=>$phase]);
            $insC=$pdo->prepare("INSERT IGNORE INTO validation_blood_components(validation_id,blood_component_id,phase_id,status) VALUES(:v,:c,:p,'active')");$insT=$pdo->prepare("INSERT INTO validation_tests(validation_id,phase_id,blood_component_id,test_id,is_required,status) SELECT :v,:p,:c,tbc.test_id,:required,'active' FROM test_blood_components tbc WHERE tbc.blood_component_id=:c2 AND tbc.test_id=:t");
            foreach($chosen as$c=>$items){$c=(int)$c;foreach((array)$items as$t=>$settings){if(empty($settings['selected']))continue;$insC->execute(['v'=>$v['id'],'c'=>$c,'p'=>$phase]);$insT->execute(['v'=>$v['id'],'p'=>$phase,'c'=>$c,'required'=>!empty($settings['required'])?1:0,'c2'=>$c,'t'=>(int)$t]);}}
            Auth::registerAudit('VALIDATION_TEST_PLAN_UPDATED','validations',(int)$v['id'],null,['phase_id'=>$phase,'tests'=>$chosen]);$pdo->commit();Flash::set('success','Plano de testes salvo.');
        }catch(\Throwable $e){if($pdo->inTransaction())$pdo->rollBack();Flash::set('error',$e->getMessage());}
        self::redirect('/validations/plan?id='.$v['id'].'&phase_id='.$phase);
    }

    public static function completePhase():void
    {
        AdminGuard::enforce('validations.complete');self::csrf('/validations');$v=self::find(true);if(!$v){self::notFound();return;}
        try{ValidationPhaseService::complete((int)$v['id'],(int)($_POST['phase_id']??0),(string)($_POST['outcome']??''),(string)($_POST['conclusion']??''));Flash::set('success','Etapa concluída.');}
        catch(\Throwable $e){Flash::set('error',$e->getMessage());}
        self::redirect('/validations/view?id='.$v['id']);
    }

    public static function createPhase():void
    {
        AdminGuard::enforce('validations.edit');self::csrf('/validations');$v=self::find(true);if(!$v){self::notFound();return;}
        try{$phase=ValidationPhaseService::createNext((int)$v['id'],(string)($_POST['name']??''),(string)($_POST['start_date']??''),!empty($_POST['copy_plan']));Flash::set('success','Próxima etapa criada.');self::redirect('/validations/plan?id='.$v['id'].'&phase_id='.$phase);}
        catch(\Throwable $e){Flash::set('error',$e->getMessage());self::redirect('/validations/view?id='.$v['id']);}
    }

    public static function completeValidation():void
    {
        AdminGuard::enforce('validations.complete');self::csrf('/validations');$v=self::find(true);if(!$v){self::notFound();return;}$conclusion=trim((string)($_POST['final_conclusion']??''));
        if($conclusion===''){Flash::set('error','Informe a conclusão final da validação.');self::redirect('/validations/view?id='.$v['id']);}
        if($v['status']!=='in_progress'){Flash::set('error','A validação precisa estar em andamento para ser concluída.');self::redirect('/validations/view?id='.$v['id']);}
        if($blocker=ValidationPhaseService::completionBlocker((int)$v['id'])){Flash::set('error',$blocker);self::redirect('/validations/view?id='.$v['id']);}
        Database::connection()->prepare("UPDATE validations SET status='completed',actual_end_date=CURDATE(),final_conclusion=:conclusion,updated_by=:user WHERE id=:id")->execute(['conclusion'=>$conclusion,'user'=>Auth::user()['id'],'id'=>$v['id']]);
        Auth::registerAudit('VALIDATION_COMPLETED','validations',(int)$v['id'],$v,['status'=>'completed','actual_end_date'=>date('Y-m-d'),'final_conclusion'=>$conclusion]);Flash::set('success','Validação concluída.');self::redirect('/validations/view?id='.$v['id']);
    }

    public static function options():void
    {
        AdminGuard::enforce('shipments.create');header('Content-Type: application/json; charset=utf-8');$unit=(int)($_GET['unit_id']??0);
        if(!$unit||!ValidationAccess::canUseUnit($unit)){echo json_encode(['validations'=>[],'message'=>'Nenhuma validação disponível para esta unidade.'],JSON_UNESCAPED_UNICODE);return;}
        [$scope,$params]=ValidationAccess::scopeSql('v');$params['unit']=$unit;
        $sql="SELECT v.id,v.pv_number,v.name,vp.id phase_id,vp.name phase_name,vp.sequence_order,(SELECT GROUP_CONCAT(DISTINCT vt.blood_component_id ORDER BY vt.blood_component_id) FROM validation_tests vt WHERE vt.validation_id=v.id AND vt.phase_id=vp.id AND vt.status='active') component_ids FROM validations v JOIN validation_phases vp ON vp.validation_id=v.id AND vp.status='active' WHERE v.unit_id=:unit AND v.status IN('planned','in_progress') AND {$scope} ORDER BY v.pv_number,vp.sequence_order";
        $q=Database::connection()->prepare($sql);$q->execute($params);$items=[];
        foreach($q->fetchAll(PDO::FETCH_ASSOC) as$row){$id=(int)$row['id'];$componentIds=array_values(array_filter(array_map('intval',explode(',',(string)$row['component_ids']))));if(!isset($items[$id]))$items[$id]=['id'=>$id,'label'=>$row['pv_number'].' — '.$row['name'],'plan_configured'=>false,'phases'=>[]];$items[$id]['plan_configured']=$items[$id]['plan_configured']||!empty($componentIds);$items[$id]['phases'][]=['id'=>(int)$row['phase_id'],'name'=>$row['phase_name'],'component_ids'=>$componentIds];}
        echo json_encode(['validations'=>array_values($items),'message'=>$items?'':'Nenhuma validação disponível para esta unidade.'],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);
    }
    private static function posted():array{return ['pv_number'=>mb_substr(trim((string)($_POST['pv_number']??'')),0,80),'name'=>mb_substr(trim((string)($_POST['name']??'')),0,180),'description'=>trim((string)($_POST['description']??''))?:null,'unit_id'=>(int)($_POST['unit_id']??0),'start_date'=>trim((string)($_POST['start_date']??'')),'expected_end_date'=>trim((string)($_POST['expected_end_date']??''))?:null,'status'=>in_array($_POST['status']??'planned',['planned','in_progress','cancelled'],true)?$_POST['status']:'planned'];}
    private static function validate(array$d,int$id=0):array{$e=[];if($d['pv_number']==='')$e[]='Informe o número PV.';if($d['name']==='')$e[]='Informe o nome.';if(!$d['unit_id'])$e[]='Informe a unidade responsável.';elseif(!ValidationAccess::canUseUnit((int)$d['unit_id']))$e[]='Unidade responsável inválida ou sem acesso.';if(!self::date($d['start_date']))$e[]='Data de início inválida.';if($d['expected_end_date']&&!self::date($d['expected_end_date']))$e[]='Previsão inválida.';return$e;}
    private static function date(string$v):bool{$d=\DateTimeImmutable::createFromFormat('!Y-m-d',$v);return$d&&$d->format('Y-m-d')===$v;}
    private static function assertSampleValidation(int$sampleId,int$validationId):void{$q=Database::connection()->prepare("SELECT 1 FROM samples WHERE id=:sample AND validation_id=:validation AND purpose='validation' LIMIT 1");$q->execute(['sample'=>$sampleId,'validation'=>$validationId]);if(!$q->fetchColumn())throw new \DomainException('Amostra inválida para esta validação.');}
    private static function find(bool$post=false):?array{$id=filter_var($post?($_POST['id']??$_POST['validation_id']??null):($_GET['id']??null),FILTER_VALIDATE_INT);if(!$id)return null;[$scope,$params]=ValidationAccess::scopeSql('v');$q=Database::connection()->prepare("SELECT v.*,u.name unit_name FROM validations v LEFT JOIN units u ON u.id=v.unit_id WHERE v.id=:id AND {$scope}");$q->execute(['id'=>$id]+$params);return$q->fetch(PDO::FETCH_ASSOC)?:null;}
    private static function csrf(string$back):void{if(!Csrf::validate($_POST['_csrf']??null)){Flash::set('error','Sessão expirada.');self::redirect($back);}}
    private static function view(string$n,array$v):void{extract($v);$flash=Flash::pull();$csrf=Csrf::token();$userAuth=Auth::user();require dirname(__DIR__).'/Views/validations/'.$n.'.php';}
    private static function redirect(string$url):never{header('Location: '.$url);exit;}
    private static function notFound():void{http_response_code(404);echo'Validação não encontrada.';}
}
